					return nil, err
				}
				tptr.Elem().Field(i).Set(reflect.ValueOf(_t))
			} else {
				tptr.Elem().Field(i).Set(selem.Field(i))
			}
		case reflect.Map:
			if selem.Field(i).IsNil() {
				continue
			}
			if MaskerType(mtag) != MaskerTypeMapStruct {
				tptr.Elem().Field(i).Set(selem.Field(i))
				continue
			}

			maskedMap := reflect.MakeMapWithSize(selem.Field(i).Type(), selem.Field(i).Len())
			iter := selem.Field(i).MapRange()
			for iter.Next() {
				v := iter.Value()
				maskedValue, err := m.maskMapStructValue(v)
				if err != nil {
					return nil, err
				}

				maskedMap.SetMapIndex(iter.Key(), maskedValue)
			}
			tptr.Elem().Field(i).Set(maskedMap)
			continue

		case reflect.Slice:
			if selem.Field(i).IsNil() {
				continue
			}
			switch {
			case selem.Field(i).Type().Elem().Kind() == reflect.String:
				orgval := selem.Field(i).Interface().([]string)
				newval := make([]string, len(orgval))
				for i, val := range selem.Field(i).Interface().([]string) {
					v, err := m.Marshal(MaskerType(mtag), val)
					if err != nil {
						return nil, err
					}
					newval[i] = v
				}
				tptr.Elem().Field(i).Set(reflect.ValueOf(newval))
			case selem.Field(i).Type().Elem().Kind() == reflect.Struct && MaskerType(mtag) == MaskerTypeStruct:
				newval := reflect.MakeSlice(selem.Field(i).Type(), 0, selem.Field(i).Len())
				for j, l := 0, selem.Field(i).Len(); j < l; j++ {
					_n, err := m.Struct(selem.Field(i).Index(j).Interface())
					if err != nil {
						return nil, err
					}
					newval = reflect.Append(newval, reflect.ValueOf(_n).Elem())
				}
				tptr.Elem().Field(i).Set(newval)
			case selem.Field(i).Type().Elem().Kind() == reflect.Ptr && MaskerType(mtag) == MaskerTypeStruct:
				newval := reflect.MakeSlice(selem.Field(i).Type(), 0, selem.Field(i).Len())
				for j, l := 0, selem.Field(i).Len(); j < l; j++ {
					if selem.Field(i).Index(j).IsNil() {
						newval = reflect.Append(newval, selem.Field(i).Index(j))
						continue
					}
					_n, err := m.Struct(selem.Field(i).Index(j).Interface())
					if err != nil {
						return nil, err
					}
					newval = reflect.Append(newval, reflect.ValueOf(_n))
				}
				tptr.Elem().Field(i).Set(newval)
			case selem.Field(i).Type().Elem().Kind() == reflect.Interface && MaskerType(mtag) == MaskerTypeStruct:
				newval := reflect.MakeSlice(selem.Field(i).Type(), 0, selem.Field(i).Len())
				for j, l := 0, selem.Field(i).Len(); j < l; j++ {
					_n, err := m.Struct(selem.Field(i).Index(j).Interface())
					if err != nil {
						return nil, err
					}
					if reflect.TypeOf(selem.Field(i).Index(j).Interface()).Kind() != reflect.Ptr {
						newval = reflect.Append(newval, reflect.ValueOf(_n).Elem())
					} else {
						newval = reflect.Append(newval, reflect.ValueOf(_n))
					}
				}
				tptr.Elem().Field(i).Set(newval)
			default:
				tptr.Elem().Field(i).Set(selem.Field(i))
			}
		case reflect.Interface:
			if selem.Field(i).IsNil() {
				continue
			}
			if MaskerType(mtag) != MaskerTypeStruct {
				continue
			}
			_t, err := m.Struct(selem.Field(i).Interface())
			if err != nil {
				return nil, err
			}
			if reflect.TypeOf(selem.Field(i).Interface()).Kind() != reflect.Ptr {
				tptr.Elem().Field(i).Set(reflect.ValueOf(_t).Elem())
			} else {
				tptr.Elem().Field(i).Set(reflect.ValueOf(_t))
			}
		}
	}

	return tptr.Interface(), nil
}

// maskMapStructValue recursively masks mapstruct values for struct, ptr, and slice shapes.
// Unsupported scalar/container leaf values are returned as-is to preserve original data.
// Note: cyclic object graphs are not handled and may cause a stack overflow.
func (m *MaskerMarshaler) maskMapStructValue(v reflect.Value) (reflect.Value, error) {
	switch v.Kind() {
	case reflect.Map:
		if v.IsNil() {
			return v, nil
		}
		maskedMap := reflect.MakeMapWithSize(v.Type(), v.Len())
		iter := v.MapRange()
		for iter.Next() {
			maskedValue, err := m.maskMapStructValue(iter.Value())
			if err != nil {
				return reflect.Value{}, err
			}
			maskedMap.SetMapIndex(iter.Key(), maskedValue)
		}
		return maskedMap, nil
	case reflect.Struct:
		nextValue, err := m.Struct(v.Interface())
		if err != nil {
			return reflect.Value{}, err
		}
		return reflect.ValueOf(nextValue).Elem(), nil
	case reflect.Ptr:
		if v.IsNil() {
			return v, nil
		}
		maskedElem, err := m.maskMapStructValue(v.Elem())
		if err != nil {
			return reflect.Value{}, err
		}
		maskedPtr := reflect.New(v.Elem().Type())
		maskedPtr.Elem().Set(maskedElem)
		return maskedPtr, nil
	case reflect.Slice:
		if v.IsNil() {
			return v, nil
		}
		maskedSlice := reflect.MakeSlice(v.Type(), 0, v.Len())
		for i := 0; i < v.Len(); i++ {
			maskedElem, err := m.maskMapStructValue(v.Index(i))
			if err != nil {
				return reflect.Value{}, err
			}
			maskedSlice = reflect.Append(maskedSlice, maskedElem)
		}
		return maskedSlice, nil
	default:
		return v, nil
	}
}

// NewMaskerMarshaler returns a new masker marshaler
// It has default maskers and default masker
// Default maskers are:
//   - NoneMasker
//   - PasswordMasker
//   - NameMasker
//   - AddressMasker
//   - EmailMasker
//   - MobileMasker
//   - TelephoneMasker
//   - IDMasker
//   - CreditMasker
//   - URLMasker
//   - AbuseMasker
//   - AllMasker
//
// Dynamic tags "first-N" and "last-N" are also supported without registration.
// Default masker is "*"
// It is used for masking sensitive data
func NewMaskerMarshaler() *MaskerMarshaler {
	return &MaskerMarshaler{
		Maskers: map[MaskerType]Masker{
			MaskerTypeNone:     &NoneMasker{},
			MaskerTypePassword: &PasswordMasker{},
			MaskerTypeName:     &NameMasker{},
			MaskerTypeAddress:  &AddressMasker{},
			MaskerTypeEmail:    &EmailMasker{},
			MaskerTypeMobile:   &MobileMasker{},
			MaskerTypeTel:      &TelephoneMasker{},
			MaskerTypeID:       &IDMasker{},
			MaskerTypeCredit:   &CreditMasker{},
			MaskerTypeURL:      &URLMasker{},
			MaskerTypeAbuse:    NewAbuseMasker(),
			MaskerTypeAll:      &AllMasker{},
		},
		masker: "*",
	}
}

// DefaultMaskerMarshaler is a default masker marshaler.
// It has the same default maskers as NewMaskerMarshaler().
var DefaultMaskerMarshaler = NewMaskerMarshaler()

func strLoop(str string, length int) string {
	return strings.Repeat(str, length)
}

func overlay(str string, overlay string, start int, end int) string {
	r := []rune(str)
	l := len(r)

	if l == 0 {
		return ""
	}

	if start < 0 {
		start = 0
	}
	if start > l {
		start = l
	}
	if end < 0 {
		end = 0
	}
	if end > l {
		end = l
	}
	if start > end {
		start, end = end, start
	}

	return string(r[:start]) + overlay + string(r[end:])
}
